    #[test]
    fn the_wire_body_answers_the_right_press() {
        // THE VANILLA startUseItem'S OWN WALK (the hitResult type ==
        // ENTITY case the switch speaks FIRST): the crosshair's verdict
        // lands the wire body, the flat Interact record the LpVec3
        // cursor carries rides the command lane — the cursor the hit
        // location minus the body's origin, the shift the
        // isShiftKeyDown speaks. The local prediction the wire body
        // never runs — the interaction the server's to resolve (the
        // SWING the result's shouldSwing speaks stays silent until the
        // echo rides), and the BLOCK case the switch never reaches.
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let n = app.world_size as f64;
        let mut body = crate::body::PlayerBody::new(
            n / 2.0 + 0.5,
            app.spawn_y as f64,
            n / 2.0 + 0.5,
            -90.0,
            0.0,
        );
        body.on_ground = true;
        app.body = Some(body);
        let (bx, bz) = {
            let b = app.body.as_ref().unwrap();
            (b.x, b.z)
        };
        // the wire zombie ON the facing line (the eye's own ray the
        // pick walks), the SERVER'S OWN id 100 the offline counter
        // never mints
        app.live_mobs_updated(vec![wire_mob_named(
            100,
            bx + 1.8,
            app.spawn_y as f64,
            bz,
            "minecraft:zombie",
        )]);
        assert_eq!(
            app.pick_mob(&app.net_mobs),
            Some(0),
            "the wire body the verdict speaks (the offline lane sleeps)"
        );
        let (tx, rx) = std::sync::mpsc::channel();
        app.live_clicks = Some(tx);
        // THE PRESS: the entity lane consumes — the BLOCK case the
        // switch never routes on an entity hit
        assert!(
            app.on_right_press(0, 0),
            "the entity hit consumed the press"
        );
        match rx.try_recv().expect("the interact") {
            crate::world_view::ContainerCommand::Interact {
                entity_id,
                cursor,
                shift,
            } => {
                assert_eq!(
                    entity_id, 100,
                    "the server's own id the record carries"
                );
                // THE CURSOR: the hit location minus the body's origin —
                // the ray along the facing line clips the box's near
                // face (the 1.8 standoff minus the half-width 0.3), the
                // eye's height the box's y span contains rides
                assert!(
                    (cursor.0 - (-0.3)).abs() < 1e-9,
                    "the near face the clip speaks, got {cursor:?}"
                );
                assert!(
                    (cursor.1 - 1.62).abs() < 1e-4,
                    "the eye's height the box contains, got {cursor:?}"
                );
                assert!(
                    cursor.2.abs() < 1e-6,
                    "the facing line the z keeps (the f32 trig's own residual), got {cursor:?}"
                );
                assert!(
                    !shift,
                    "the unpressed shift the record's own field keeps"
                );
            }
            other => panic!("expected an interact, got {other:?}"),
        }
        assert!(
            rx.try_recv().is_err(),
            "nothing else the press speaks — no swing, the verdict the server's own"
        );
        // THE SHIFT: the sneak key the record's fourth field rides
        app.on_shift_down(true);
        assert!(app.on_right_press(0, 0), "the press consumed again");
        match rx.try_recv().expect("the shifted interact") {
            crate::world_view::ContainerCommand::Interact { shift, .. } => {
                assert!(
                    shift,
                    "the pressed shift the isShiftKeyDown speaks"
                );
            }
            other => panic!("expected an interact, got {other:?}"),
        }
    }

    #[test]
    fn the_offline_entity_pass_skips_the_block_lane() {
        // THE ENTITY CASE'S OWN FALL-THROUGH (the vanilla startUseItem's
        // walk): the offline body the pick speaks PASSes — the
        // ZOMBIE's own mob.interact table empty (the sheep's shear the
        // table's first entry — its own test speaks) — and the BLOCK
        // case the switch never reaches on an entity hit: the held
        // dirt the ray aims at a face BEHIND the body never places
        // (the vanilla never places through the body the crosshair
        // picked), the press the item lane's own PASS refuses.
        let mut app = App::new(3);
        app.enter_world();
        app.offline_held_updated(Some("item/dirt"));
        let size = app.offline_world.as_ref().unwrap().size_blocks();
        let c = size / 2;
        let top = app.spawn_y;
        app.offline_camera_updated(crate::camera::Camera {
            pos: crate::math::Vec3::new(c as f32 + 0.5, top as f32 + 4.0, c as f32 + 0.5),
            yaw: 0.0,
            pitch: -std::f32::consts::FRAC_PI_2,
        });
        // the offline body IN the cell the straight-down ray walks (the
        // box the ray enters at the top face — 2.05 below the eye, the
        // block's own hit 4.0 the strict compare loses)
        app.mobs.push(crate::mob::Zombie::new(
            7,
            c as f64 + 0.5,
            top as f64,
            c as f64 + 0.5,
            3,
        ));
        assert_eq!(
            app.pick_mob(&app.mobs),
            Some(0),
            "the offline body the verdict speaks (the wire lane sleeps)"
        );
        let (tx, rx) = std::sync::mpsc::channel();
        app.live_clicks = Some(tx);
        assert!(
            !app.on_right_press(0, 0),
            "the entity PASS + the dirt's own PASS refuse the press"
        );
        assert!(
            rx.try_recv().is_err(),
            "no UseItemOn the entity hit ever routes"
        );
        assert_eq!(
            app.offline_world.as_ref().unwrap().get(c, top, c),
            crate::world::AIR,
            "the placement cell the body's own verdict guards"
        );
        // THE BODY STEPS ASIDE: the pick misses, the BLOCK case speaks —
        // the same press the block lane's own placement answers
        app.mobs.clear();
        assert!(
            app.on_right_press(0, 0),
            "the block hit consumed the press"
        );
        assert_eq!(
            app.offline_world.as_ref().unwrap().get(c, top, c),
            crate::world::DIRT,
            "the held dirt landed the block case speaks"
        );
    }

    #[test]
    fn the_right_press_shears_the_offline_sheep() {
        // THE TABLE'S FIRST VERDICT (the vanilla startUseItem's ENTITY
        // case — the offline prediction `player.interactOn` returns):
        // the sheep the pick lands, the shears the held stack speaks —
        // the Shear the shearing/sheep/red table rolls, the press the
        // SUCCESS_SERVER merge consumes (the voice the playSound law
        // rides, the loot the copyWithCount(1) singles spawn at the
        // body's feet, the swing the SwingSource.SERVER starts); the
        // sheared bit closes the gate — the second press the item
        // lane's own PASS refuses (the shears no use def carry).
        let mut app = App::new(3);
        app.enter_world();
        app.offline_held_updated(Some("item/shears"));
        let size = app.offline_world.as_ref().unwrap().size_blocks();
        let c = size / 2;
        let top = app.spawn_y;
        app.offline_camera_updated(crate::camera::Camera {
            pos: crate::math::Vec3::new(c as f32 + 0.5, top as f32 + 4.0, c as f32 + 0.5),
            yaw: 0.0,
            pitch: -std::f32::consts::FRAC_PI_2,
        });
        let mut sheep =
            crate::mob::Zombie::new(7, c as f64 + 0.5, top as f64, c as f64 + 0.5, 3);
        sheep.kind = crate::mob::MobKind::Sheep;
        sheep.wool_color = 14;
        app.mobs.push(sheep);
        assert_eq!(
            app.pick_mob(&app.mobs),
            Some(0),
            "the offline sheep the verdict speaks"
        );
        assert!(
            app.on_right_press(0, 0),
            "the Shear verdict consumed the press"
        );
        // THE WOOL'S OWN TRUTH: the bit set, the singles spawned (the
        // App's own mob_rng first draw — the seed 0x5EED_10CA's % 3
        // speaks 1), each one red_wool count 1 at the body's feet
        assert!(app.mobs[0].sheared, "setSheared(true) the press speaks");
        let red = crate::mob::wire_id("red_wool").expect("red_wool the table draws");
        assert_eq!(app.drops.len(), 1, "the mob_rng's own first roll");
        assert_eq!(app.drops[0].item, red, "the red table's own item");
        assert_eq!(app.drops[0].count, 1, "the copyWithCount(1) law");
        assert!(
            (app.drops[0].x - (c as f64 + 0.5)).abs() < 0.5,
            "the spawnAtLocation law's own x"
        );
        // THE VOICE: the playSound(SHEEP_SHEAR, PLAYERS, 1.0, 1.0)
        // the shear's own walk opens with
        assert!(
            app.sounds
                .events
                .iter()
                .any(|e| e.starts_with("entity.sheep.shear ")),
            "the shear's own voice the lane carries"
        );
        // THE SWING: the SwingSource.SERVER the verdict carries
        assert!(app.swing.swinging, "the press swung the arm");
        // THE CLOSED GATE: the second press falls to the item lane —
        // the shears the use def never speak, the PASS refuses
        assert!(
            !app.on_right_press(0, 0),
            "the sheared sheep the gate closed"
        );
    }

    #[test]
    fn the_right_press_feeds_the_offline_sheep() {
        // THE FOOD ARM'S OWN PRESS (the Animal.mobInteract walk the
        // offline prediction speaks): the wheat the held stack talks,
        // the ADULT arm the canFallInLove gate opens — the setInLove
        // the 600 arms, the SUCCESS_SERVER the press consumes (the
        // swing the SwingSource.SERVER starts, the EAT VOICE the
        // playEatingSound base keeps SILENT — the Sheep the override
        // never speaks, the jar's own law); the second press the
        // in-love adult keeps — the CONSUME the fallback speaks (the
        // press consumed, SwingSource.NONE no swing restarts)
        let mut app = App::new(3);
        app.enter_world();
        app.offline_held_updated(Some("item/wheat"));
        let size = app.offline_world.as_ref().unwrap().size_blocks();
        let c = size / 2;
        let top = app.spawn_y;
        app.offline_camera_updated(crate::camera::Camera {
            pos: crate::math::Vec3::new(c as f32 + 0.5, top as f32 + 4.0, c as f32 + 0.5),
            yaw: 0.0,
            pitch: -std::f32::consts::FRAC_PI_2,
        });
        let mut sheep =
            crate::mob::Zombie::new(7, c as f64 + 0.5, top as f64, c as f64 + 0.5, 3);
        sheep.kind = crate::mob::MobKind::Sheep;
        app.mobs.push(sheep);
        assert_eq!(
            app.pick_mob(&app.mobs),
            Some(0),
            "the offline sheep the pick speaks"
        );
        assert!(
            app.on_right_press(0, 0),
            "the Feed verdict consumed the press"
        );
        // THE LOVE'S OWN TRUTH: the clock the 600 arms, the swing the
        // SERVER word starts, the loot lane NO drop speaks (the food
        // the wool's table never is)
        assert_eq!(app.mobs[0].in_love, 600, "setInLove's own 600");
        assert!(app.swing.swinging, "the press swung the arm");
        assert!(app.drops.is_empty(), "the feed the loot lane never speaks");
        // THE SILENCE: the Sheep the base's own empty playEatingSound
        // keeps — no voice event the lane carries
        assert!(
            !app.sounds
                .events
                .iter()
                .any(|e| e.contains(".eat")),
            "the sheep's feed the silent law keeps"
        );
        // the swing's own clock walks to rest (the 6-tick duration)
        for _ in 0..8 {
            app.swing.tick();
        }
        assert!(!app.swing.swinging, "the swing the clock completes");
        // THE CONSUME FALLBACK: the in-love adult the canFallInLove
        // gate refuses — the press consumed, NO swing restarts, the
        // clock the fallback never changes
        assert!(
            app.on_right_press(0, 0),
            "the CONSUME verdict consumed the press"
        );
        assert!(!app.swing.swinging, "the CONSUME no swing starts");
        assert_eq!(
            app.mobs[0].in_love, 600,
            "the fallback the clock never changes (no ticks walked)"
        );
    }

